using D2NG.Core.D2GS.Act;
using D2NG.Core.D2GS.Enums;
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace D2NG.Core.LevelData;

/// <summary>
/// The monster level of every area per difficulty, for classic and for expansion games, from the game's own levels
/// table. Generated by the MpqData tool.
/// </summary>
/// <remarks>
/// Classic is Normal plus 25 in Nightmare and plus 50 in Hell for every area, but expansion is not: its Nightmare and
/// Hell act 1 levels sit far higher (Blood Moor 36 and 67, against 26 and 51 in classic).
/// </remarks>
public sealed class AreaLevelTable
{
    private readonly Dictionary<Area, AreaLevels> _byArea;

    private AreaLevelTable(Dictionary<Area, AreaLevels> byArea, AreaLevelSource source)
    {
        _byArea = byArea;
        Source = source;
    }

    public AreaLevelSource Source { get; }

    public int Count => _byArea.Count;

    public static AreaLevelTable FromEntries(IEnumerable<AreaLevels> entries, AreaLevelSource source)
    {
        var byArea = new Dictionary<Area, AreaLevels>();
        foreach (var entry in entries)
        {
            byArea[entry.Area] = entry;
        }

        return new AreaLevelTable(byArea, source);
    }

    public static AreaLevelTable Load(string path)
    {
        var file = JsonSerializer.Deserialize<AreaLevelFile>(File.ReadAllText(path), SerializerOptions);
        return FromEntries(file.Areas, file.Source);
    }

    public void Save(string path)
    {
        var file = new AreaLevelFile { Source = Source, Areas = [.. _byArea.Values] };
        file.Areas.Sort((left, right) => left.Area.CompareTo(right.Area));
        File.WriteAllText(path, JsonSerializer.Serialize(file, SerializerOptions));
    }

    /// <summary>The monster level of an area, or null for an area without monsters or not in the table.</summary>
    public int? MonsterLevel(Area area, Difficulty difficulty, bool expansion)
    {
        if (!_byArea.TryGetValue(area, out var levels))
        {
            return null;
        }

        var row = expansion ? levels.Expansion : levels.Classic;
        var index = (int)difficulty;
        return row != null && index < row.Length && row[index] > 0 ? row[index] : null;
    }

    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter() }
    };

    private sealed class AreaLevelFile
    {
        public AreaLevelSource Source { get; set; }
        public List<AreaLevels> Areas { get; set; } = [];
    }
}

/// <summary>One area's monster levels, Normal, Nightmare and Hell.</summary>
public sealed class AreaLevels
{
    public Area Area { get; set; }

    public string Name { get; set; }

    public int[] Classic { get; set; }

    public int[] Expansion { get; set; }
}

public sealed class AreaLevelSource
{
    public string GameDirectory { get; set; }
    public string Archive { get; set; }
    public string File { get; set; }
    public string Sha256 { get; set; }
    public int RecordCount { get; set; }
    public int RecordSize { get; set; }
    public DateTime ExtractedUtc { get; set; }
}
